-- ============================================================================
-- inspect_prec_miss_content.sql
-- 정답 chunk와, 그 대신 상위로 뽑힌 오답 chunk들의 실제 title/content를 나란히 비교합니다.
-- 왜 엉뚱한 사건이 더 유사하다고 판단됐는지 눈으로 확인하기 위함입니다.
-- ============================================================================

SELECT chunk_id, title, content
FROM legal_chunks
WHERE chunk_id IN (
    -- Q1: 정답 vs 오답
    'prec_204222_head_1',   -- 정답 (사문서변조·사기미수)
    'prec_83768_body_2', 'prec_83768_body_5',
    'prec_68147_head', 'prec_68147_body_1',
    'prec_204222_body_5',   -- 실제로 뽑힌 정답 사건의 다른 chunk

    -- Q2: 정답 vs 오답
    'prec_184767_head_1',   -- 정답 (횡령·범죄수익은닉)
    'prec_185962_head', 'prec_186058_head', 'prec_77765_head', 'prec_182878_head',

    -- Q4: 정답 vs 오답
    'prec_229805_head_1',   -- 정답 (뇌물수수·사기·배임수재 등)
    'prec_148924_body_9', 'prec_117947_body_13', 'prec_239935_head',
    'prec_183678_body_4', 'prec_188040_body_9'
)
ORDER BY chunk_id;

